private void
set_test_type(struct magic *mstart, struct magic *m)
{
        switch (m->type) {
        case FILE_BYTE:
        case FILE_SHORT:
        case FILE_LONG:
        case FILE_DATE:
        case FILE_BESHORT:
        case FILE_BELONG:
        case FILE_BEDATE:
        case FILE_LESHORT:
        case FILE_LELONG:
        case FILE_LEDATE:
        case FILE_LDATE:
        case FILE_BELDATE:
        case FILE_LELDATE:
        case FILE_MEDATE:
        case FILE_MELDATE:
        case FILE_MELONG:
        case FILE_QUAD:
        case FILE_LEQUAD:
        case FILE_BEQUAD:
        case FILE_QDATE:
        case FILE_LEQDATE:
        case FILE_BEQDATE:
        case FILE_QLDATE:
        case FILE_LEQLDATE:
        case FILE_BEQLDATE:
        case FILE_QWDATE:
        case FILE_LEQWDATE:
        case FILE_BEQWDATE:
        case FILE_FLOAT:
        case FILE_BEFLOAT:
        case FILE_LEFLOAT:
        case FILE_DOUBLE:
        case FILE_BEDOUBLE:
        case FILE_LEDOUBLE:
        case FILE_BEVARINT:
        case FILE_LEVARINT:
        case FILE_DER:
        case FILE_GUID:
        case FILE_OFFSET:
        case FILE_MSDOSDATE:
        case FILE_BEMSDOSDATE:
        case FILE_LEMSDOSDATE:
        case FILE_MSDOSTIME:
        case FILE_BEMSDOSTIME:
        case FILE_LEMSDOSTIME:
                mstart->flag |= BINTEST;
                break;
        case FILE_STRING:
        case FILE_PSTRING:
        case FILE_BESTRING16:
        case FILE_LESTRING16:
                /* Allow text overrides */
                if (mstart->str_flags & STRING_TEXTTEST)
                        mstart->flag |= TEXTTEST;
                else
                        mstart->flag |= BINTEST;
                break;
        case FILE_REGEX:
        case FILE_SEARCH:
                /* Check for override */
                if (mstart->str_flags & STRING_BINTEST)
                        mstart->flag |= BINTEST;
                if (mstart->str_flags & STRING_TEXTTEST)
                        mstart->flag |= TEXTTEST;

                if (mstart->flag & (TEXTTEST|BINTEST))
                        break;

                /* binary test if pattern is not text */
                if (file_looks_utf8(m->value.us, CAST(size_t, m->vallen), NULL,
                    NULL) <= 0)
                        mstart->flag |= BINTEST;
                else
                        mstart->flag |= TEXTTEST;
                break;
        case FILE_DEFAULT:
                /* can't deduce anything; we shouldn't see this at the
                   top level anyway */
                break;
        case FILE_INVALID:
        default:
                /* invalid search type, but no need to complain here */
                break;
        }
}

private int
addentry(struct magic_set *ms, struct magic_entry *me,
   struct magic_entry_set *mset)
{
        size_t i = me->mp->type == FILE_NAME ? 1 : 0;
        if (mset[i].me == NULL || mset[i].count == mset[i].max) {
                struct magic_entry *mp;

                size_t incr = mset[i].max + ALLOC_INCR;
                if ((mp = CAST(struct magic_entry *,
                    realloc(mset[i].me, sizeof(*mp) * incr))) ==
                    NULL) {
                        file_oomem(ms, sizeof(*mp) * incr);
                        return -1;
                }
                (void)memset(&mp[mset[i].count], 0, sizeof(*mp) *
                    ALLOC_INCR);
                mset[i].me = mp;
                mset[i].max = incr;
        }
        mset[i].me[mset[i].count++] = *me;
        memset(me, 0, sizeof(*me));
        return 0;
}

